"""Ring detachment tension and four-pair sensor calibration."""
from pathlib import Path
import json
import numpy as np
def analyze(experiment_dir):
 root=Path(experiment_dir);cfg=json.loads((root/'experiment.json').read_text(encoding='utf-8'));p=cfg['parameters']
 cal=np.genfromtxt(root/'data/calibration.csv',delimiter=',',names=True);pull=np.genfromtxt(root/'data/pulls.csv',delimiter=',',names=True);dia=np.genfromtxt(root/'data/diameters.csv',delimiter=',',names=True)
 V=(cal['loading_mv']+cal['unloading_mv'])/2;dV=V[4:]-V[:4];delta=float(dV.mean());K=p['gravity_m_s2']*.002/delta;F=cal['mass_mg']*1e-6*p['gravity_m_s2'];xc=V-V.mean();yc=F-F.mean();Kls=float(xc@yc/(xc@xc));intercept=float(F.mean()-Kls*V.mean());corr=float(xc@yc/np.sqrt((xc@xc)*(yc@yc)))
 differences=pull['before_mv']-pull['after_mv'];dmean=float(differences.mean());di=float(dia['inner_mm'].mean());do=float(dia['outer_mm'].mean());L=np.pi*(di+do)/1000;alpha=K*dmean/L
 ua=lambda x:float(np.std(x,ddof=1)/np.sqrt(len(x)))
 quant_v=p['voltage_resolution_mv']/np.sqrt(12);quant_d=p['diameter_resolution_mm']/np.sqrt(12)
 ud=np.hypot(ua(dV),quant_v/2);up=np.hypot(ua(differences),np.sqrt(2/5)*quant_v);uL=np.pi*np.sqrt(ua(dia['inner_mm'])**2+ua(dia['outer_mm'])**2+2*quant_d**2/5)/1000;uK=K*ud/delta;ualpha=alpha*np.sqrt((uK/K)**2+(up/dmean)**2+(uL/L)**2)
 vals=[('calibration_difference',delta,'mV','四组逐差平均'),('conversion_difference',K,'N/mV','逐差转换系数'),('conversion_regression',Kls,'N/mV','最小二乘转换系数'),('calibration_intercept',intercept,'N','标定拟合截距'),('calibration_correlation',corr,'1','标定相关系数'),('mean_pull_difference',dmean,'mV','拉脱读数差平均'),('mean_inner_diameter',di,'mm','平均内径'),('mean_outer_diameter',do,'mm','平均外径'),('contact_length',L,'m','接触线总长度'),('surface_tension',alpha,'N/m','逐差法表面张力系数'),('surface_tension_regression',Kls*dmean/L,'N/m','回归标定表面张力系数'),('conditional_uncertainty',ualpha,'N/m','条件标准不确定度'),('relative_deviation',100*abs(alpha-p['reference_n_m'])/p['reference_n_m'],'%','相对参考值差异')]
 metrics={key:{'value':float(val),'unit':unit,'label':label} for key,val,unit,label in vals};metrics['surface_tension']['uncertainty']=float(ualpha)
 tables={'calibration':{'headers':['质量 / mg','增重读数 / mV','减重读数 / mV','平均读数 / mV','四点逐差 / mV'],'rows':[[float(m),float(vp),float(vm),float(v),float(dV[i]) if i<4 else '—'] for i,(m,vp,vm,v) in enumerate(zip(cal['mass_mg'],cal['loading_mv'],cal['unloading_mv'],V))]},'pulls':{'headers':['次数','$V_1 / \\mathrm{mV}$','$V_2 / \\mathrm{mV}$','$V_1-V_2 / \\mathrm{mV}$'],'rows':[[int(row['trial']),float(row['before_mv']),float(row['after_mv']),float(d)] for row,d in zip(pull,differences)]+[['平均值','—','—',dmean]]},'diameters':{'headers':['测量次数','1','2','3','4','5','平均值 / mm'],'rows':[['内径 / mm',*dia['inner_mm'].tolist(),di],['外径 / mm',*dia['outer_mm'].tolist(),do]]},'uncertainty':{'headers':['物理量','估值','A类标准不确定度','条件合成标准不确定度','单位'],'rows':[['逐差平均',delta,ua(dV),float(ud),'mV'],['转换系数',K,'—',float(uK),'N/mV'],['拉脱读数差平均',dmean,ua(differences),float(up),'mV'],['接触线长度',L,'—',float(uL),'m'],['表面张力系数',alpha,'—',float(ualpha),'N/m']]}}
 return {'metrics':metrics,'tables':tables,'series':{'calibration':{'x':V.tolist(),'y':F.tolist(),'x_label':'平均电压 / mV','y_label':'砝码重力 / N','fit':True},'pull_sequence':{'x':pull['trial'].tolist(),'y':differences.tolist(),'x_label':'拉脱序号','y_label':'拉脱前后电压差 / mV'}},'notes':['量化读数假定独立、误差半宽为半分辨力，均匀分布；B类按线性组合及均值系数传播。','砝码质量、g、润湿、液膜重量及迟滞漂移误差未量化，合成为条件预算。']}
def explore(key,result):
 import plotly.graph_objects as go
 if key!='calibration-method':raise KeyError(key)
 rows=result['tables']['pulls']['rows'][:5];x=[row[0] for row in rows];V=np.array([row[3] for row in rows]);L=result['metrics']['contact_length']['value'];ks=[result['metrics'][k]['value'] for k in ['conversion_difference','conversion_regression']];ys=[k*V/L for k in ks]
 fig=go.Figure(go.Scatter(x=x,y=ys[0],mode='lines+markers',line={'color':'black'},marker={'color':'black','symbol':'circle-open','size':10}));fig.update_layout(template='plotly_white',font={'family':'Times New Roman, SimSun','size':18},width=900,height=580,xaxis_title='拉脱序号',yaxis_title='表面张力系数 / (N m⁻¹)',margin={'l':90,'r':30,'t':80,'b':130},updatemenus=[{'buttons':[{'label':label,'method':'restyle','args':[{'y':[y.tolist()]}]} for label,y in zip(['逐差标定','最小二乘标定'],ys)],'x':.5,'y':1.15,'xanchor':'center','yanchor':'top'}]);fig.update_xaxes(showline=True,linecolor='black',gridcolor='#e3e3e3');fig.update_yaxes(showline=True,linecolor='black',gridcolor='#e3e3e3');return fig
